const $=s=>document.querySelector(s),money=n=>n.toLocaleString('ko-KR')+'원';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[],category='전체',selected={};
try{const value=JSON.parse(localStorage.getItem('office-picks-list')||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))selected=value}catch{}
function validQty(v){const n=Number(v);return Number.isFinite(n)?Math.max(1,Math.min(999,Math.floor(n))):1}
function save(){try{localStorage.setItem('office-picks-list',JSON.stringify(selected))}catch{}}
function render(){
 const query=$('#search').value.trim().toLowerCase();let list=products.filter(p=>(category==='전체'||p.category===category)&&(`${p.name} ${p.comment} ${p.category}`).toLowerCase().includes(query));
 const sort=$('#sort').value;if(sort==='price')list.sort((a,b)=>a.price-b.price);if(sort==='reviews')list.sort((a,b)=>b.reviews-a.reviews);if(sort==='rating')list.sort((a,b)=>b.rating-a.rating||b.reviews-a.reviews);
 $('#result-count').textContent=list.length;$('#empty').hidden=list.length>0;
 $('#products').innerHTML=list.map(p=>`<article class="product" id="product-${p.id}"><div class="product-top"><div><div class="image-wrap">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" decoding="async">`:`<span class="image-placeholder" aria-hidden="true">▦</span>`}<span class="product-index">${String(p.id).padStart(2,'0')}</span></div>${p.imageCaption?`<span class="image-caption">${esc(p.imageCaption)}</span>`:''}</div><div><span class="product-tag">${esc(p.category)}</span><h3>${esc(p.name)}</h3><div class="price-row"><strong>${money(p.price)}</strong><span class="unit">${esc(p.unit)}</span></div><div class="product-facts"><span>${esc(p.shipping)}</span><span class="rating">★ 약 ${p.rating.toFixed(1)}</span><span>리뷰 ${p.reviews.toLocaleString('ko-KR')}개</span></div></div></div><aside class="review-note"><span class="review-label">작성자의 구매 메모 · 리뷰 해석</span><p>${esc(p.comment)}</p></aside><div class="product-bottom"><a class="buy" href="${esc(p.url)}" rel="sponsored noopener noreferrer" target="_blank">쿠팡에서 구성 확인 <span aria-hidden="true">↗</span></a><button class="add ${selected[p.id]?'selected':''}" data-add="${p.id}" aria-pressed="${Boolean(selected[p.id])}" aria-label="${esc(p.name)} 구매 후보 ${selected[p.id]?'빼기':'담기'}">${selected[p.id]?'✓ 담아둠':'+ 후보 담기'}</button></div></article>`).join('');
 renderPurchase();
}
function renderPurchase(){
 const list=products.filter(p=>selected[p.id]);let total=0,qty=0;
 $('#purchase-list').innerHTML=list.length?list.map(p=>{const q=validQty(selected[p.id]);selected[p.id]=q;total+=p.price*q;qty+=q;return `<div class="purchase-row"><div class="purchase-name">${esc(p.name)}<small>${esc(p.unit)} · 판매 구성당 ${money(p.price)}</small></div><div class="quantity"><button data-step="-1" data-id="${p.id}" aria-label="${esc(p.name)} 수량 줄이기">−</button><input type="number" min="1" max="999" step="1" value="${q}" data-qty="${p.id}" aria-label="${esc(p.name)} 판매 구성 수량"><button data-step="1" data-id="${p.id}" aria-label="${esc(p.name)} 수량 늘리기">+</button></div><span class="row-total">${money(p.price*q)}</span><button class="remove" data-remove="${p.id}" aria-label="${esc(p.name)} 후보 삭제">×</button></div>`}).join(''):'<p class="purchase-empty">상품의 ‘후보 담기’를 눌러 이번 주문 목록을 만들어 보세요.</p>';
 $('#total').textContent=money(total);$('#selected-summary').textContent=`${list.length}종 · ${qty}세트`;$('#header-count').textContent=list.length;$('#csv').disabled=!list.length;
}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(t=>{const on=t===b;t.classList.toggle('active',on);t.setAttribute('aria-pressed',String(on))});render()});
$('#search').oninput=render;$('#sort').onchange=render;
$('#products').onclick=e=>{const b=e.target.closest('[data-add]');if(!b)return;const id=b.dataset.add;if(selected[id])delete selected[id];else selected[id]=1;save();render()};
$('#purchase-list').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove)delete selected[b.dataset.remove];else if(b.dataset.step)selected[b.dataset.id]=validQty((selected[b.dataset.id]||1)+Number(b.dataset.step));else return;save();render()};
$('#purchase-list').onchange=e=>{const id=e.target.dataset.qty;if(!id)return;selected[id]=validQty(e.target.value);save();renderPurchase()};
$('#reset').onclick=()=>{category='전체';$('#search').value='';document.querySelector('[data-category="전체"]').click()};
function downloadFile(data,type,name){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#csv').onclick=()=>{const rows=[['상품명','용도','단가','구성 가격(원)','판매 구성 수량','예상 상품 금액(원)','배송','평점(약값)','리뷰 수','상품 링크','작성자의 구매 메모']];for(const p of products.filter(p=>selected[p.id])){const q=validQty(selected[p.id]);rows.push([p.name,p.category,p.unit,p.price,q,p.price*q,p.shipping,p.rating,p.reviews,p.url,p.comment])}const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');downloadFile(csv,'text/csv;charset=utf-8','오피스-구매후보-2026-10-10.csv')};
function init(data){products=data;const ids=new Set(data.map(p=>String(p.id)));selected=Object.fromEntries(Object.entries(selected).filter(([id,q])=>ids.has(id)&&Number(q)>0).map(([id,q])=>[id,validQty(q)]));render()}
fetch('products.json').then(r=>{if(!r.ok)throw Error('fetch');return r.json()}).then(init).catch(()=>{$('#products').innerHTML='<p>상품을 불러오지 못했습니다. 페이지를 새로고침해 주세요.</p>'});
